const episodes = Array.from({length:11}, (_, i) => ({
  number:i+1,
  title:`قسمت ${i+1}`,
  paragraphs:[]
}));
episodes[10] = {
  number:23,
  title:'ظالم',
  paragraphs:"تصویرها صبح تکثیر شدند. اول روی دیوارهای پایتخت. بعد روی دروازه‌های شهر. بعد روی پارچه‌هایی که بازرگانان به شهرهای دیگر می‌بردند. آرن با تاجی سیاه. چشمانی بی‌احساس و دستی که بر نقشه‌ای از الیورا قرار گرفته بود. زیر تصویر نوشته بودند: «او هنوز تاج نخواسته است.« اما هیچ‌کس نپرسید چه کسی تاج را نقاشی کرده. تصویر، پیش از حقیقت حرکت کرده بود.\nآرن تصویر خودش را عصر همان روز دید. در بازار مردی داشت آن را بین مردم پخش می‌کرد. آرن یکی برداشت. چند لحظه نگاهش کرد. یورن گفت:\n«پاره‌ش کن.« آرن گفت:\n«نه.«\n«چرا؟«\n«چون اگر پاره‌ش کنم، فردا هزار نسخه‌ی دیگه چاپ می‌کنن.« یورن گفت:\n«پس چی کار کنیم؟« آرن تصویر را تا کرد.\n«هیچ‌چیز.« یورن خندید.\n«این جواب جدیدته؟« آرن گفت:\n«نه.« نگاهش به تصویر خودش افتاد.\n«دارم می‌فهمم که بعضی چیزها با مقابله بزرگ‌تر می‌شن.«\nآن شب، آرن از شهر خارج نشد و در میدان ماند. مردم اطرافش جمع شدند. یکی پرسید:\n«واقعاً می‌خوای پادشاه بشی؟« آرن گفت:\n«نه.« دیگری گفت:\n«پس چرا نمی‌ری؟«\n«کجا؟«\n«هرجا که مردم تو رو نشناسن.« آرن لبخند زد.\n«دیگه جایی نمونده.«\nصبح روز بعد، اولین فرمان واقعی صادر شد، اما نه از طرف آرن، از طرف شورای پیشگیری. «هر شهر موظف است یک نماینده برای نظارت بر رفتار آرن تعیین کند.«\nنمایندگان وارد شهر شدند. نه با شمشیر. با دفتر. آنها نشستند. نوشتند. ثبت کردند. هر گفت‌وگوی آرن را گزارش کردند. هر تصمیمش را. هر اشتباهش را. هر سکوتش را. حتی خنده‌هایش را. در یکی از گزارش‌ها نوشته شد: «سوژه امروز سه بار خندید.« در گزارش بعد: «خنده‌ی او ممکن است نشانه‌ی ایجاد اعتماد باشد.« و در سوم: «اعتماد به او در میان مردم در حال افزایش است.« آرن وقتی این گزارش را دید، گفت:\n«پس خندیدن هم جرم شد؟« یورن گفت:\n«برای تو ظاهراً بله.«\nاما چیزی عجیب‌تر در حال رخ دادن بود. مردم شروع کردند به آوردن مشکلاتشان نزد آرن. نه چون او را خدا می‌دانستند. چون شورای شهر دیگر پاسخ نمی‌داد. قاضی‌ها می‌ترسیدند تصمیم بگیرند. فرمانداران منتظر دستور شورا بودند. شورا هم منتظر بود ببیند آرن چه می‌کند و آرن، ناخواسته، در مرکز همه‌ی تصمیم‌ها قرار گرفته بود. زنی آمد و گفت:\n«شوهرم زمین منو گرفته.« آرن گفت:\n«پیش قاضی برو.« زن گفت:\n«قاضی می‌گه باید از تو اجازه بگیرم.« مردی آمد:\n«کارخونه‌مون تعطیل شده.« آرن گفت:\n«به صاحبش بگو.« گفت:\n«صاحبش می‌گه منتظر فرمان توئه.« کودکی آمد:\n«معلممون می‌گه تا تو تصمیم نگیری، کلاس تشکیل نمی‌شه.« آرن سرش را میان دست‌هایش گرفت.\n«من که هیچ‌وقت نگفتم تصمیم می‌گیرم.« یورن گفت:\n«ولی همه دارن منتظر تصمیم تو می‌مونن.« آرن آهسته گفت:\n«این بدتره.«\nسه روز بعد، شورای شهر رسماً اعلام کرد: «آرن، مرجع موقت حل اختلافات عمومی خواهد بود.« آرن به محض شنیدن خبر، به ساختمان شورا رفت. در را باز کرد.\n«چه کسی اینو گفته؟« رئیس شورا گفت:\n«مردم.«\n«کدوم مردم؟«\n«همه.« آرن گفت:\n«من قبول نکردم.« رئیس شورا لبخند زد.\n«لازم نیست.«\nآن شب آرن خوابش نبرد. کنار پنجره نشست. روی میز، همان حلقه‌ای بود که نگهبانان به او داده بودند. دایره‌ای کامل. آرن آن را در دست گرفت. چیزی حس کرد. فشار خفیفی مثل ضربان. ناگهان تصویرهایی دید. شهری که در آن مردم هر اختلافی را نزد او می‌آوردند. شهری که او عدالت برقرار می‌کرد. شهری که به او اعتماد می‌کرد. بعد شهر بزرگ‌تر شد. بعد شهرها،بعد کشورها و بعد... همه‌چیز ساکت شد. هیچ‌کس تصمیمی نمی‌گرفت. همه منتظر بودند. آرن حلقه را رها کرد و تصویر ناپدید شد. زیر لب گفت:\n«این نجات نیست.« صدایی از تاریکی گفت:\n«نه.« آرن برگشت. لیان آنجا ایستاده بود.\n«چطور وارد شدی؟«\n«در باز بود.«\n«دروغ نگو.« لیان لبخند بسیار کمرنگی زد.\n«هنوز هم مثل مادرت سؤال می‌پرسی.« آرن یخ زد.\n«مادرم رو می‌شناختی؟« لیان چیزی نگفت. آرن نزدیک شد.\n«گفتم مادرم رو می‌شناختی؟«\n«بله.«\n«از کی؟«\n«پیش از تولدت.« آرن نفسش را حبس کرد.\n«چرا هیچ‌وقت نگفتی؟« لیان گفت:\n«چون می‌دانستم اگر بدانی، او را تبدیل به نقطه‌ی ضعف می‌کنی.« آرن با خشم گفت:\n«من؟ یا شما؟« لیان سکوت کرد. آرن گفت:\n«شما حتی مادرم رو هم وارد داستان کردید.«\n«نه.«\n«پس چرا همه‌چیز به من می‌رسه؟« لیان گفت:\n«چون تو مرکز این داستان نیستی.« آرن متوقف شد.\n«چی؟« لیان نزدیک پنجره رفت.\n«این داستان درباره‌ی تو نیست.«\n«پس درباره‌ی چیه؟« لیان گفت:\n«درباره‌ی ما.« آرن چیزی نگفت. لیان ادامه داد:\n«هزار سال پیش، ما از چیزی ترسیدیم که هنوز وجود نداشت و برای جلوگیری از آن، تصمیم گرفتیم آینده را تعریف کنیم. بعد برای دفاع از تعریفمان، جامعه ساختیم. بعد قانون. بعد ارتش. بعد علم. بعد تاریخ.« مکث کرد.\n«و حالا تو.« آرن گفت:\n«من نتیجه‌ام.«\n«بخشی از نتیجه.«\n«و بخش دیگه؟« لیان به بیرون نگاه کرد.\n«هرکس که در این هزار سال، یک تصمیم کوچک گرفت.« آرن آهسته گفت:\n«پس هیچ‌کس مقصر نیست.« لیان فوراً گفت:\n«نه.« برگشت.\n«این خطرناک‌ترین نتیجه‌ای است که می‌توانی بگیری.« سکوت. لیان گفت:\n«اینکه یک نتیجه از هزاران علت آمده، به این معنا نیست که هیچ‌کس مسئول نیست.«\n«پس چه کسی؟«\n«هرکس در جایی که می‌توانست انتخاب دیگری کند.« آرن گفت:\n«و اگر انتخاب دیگری نمی‌دید؟« لیان پاسخ داد:\n«آن‌وقت مسئول نادیدن خودش است.« آرن خندید. تلخ.\n«پس همه مسئولیم.« لیان گفت:\n«شاید.«\n«و تو؟«\n«بیشتر از بسیاری.«\n«چرا؟« لیان به چشمانش نگاه کرد.\n«چون من اولین کسی بودم که پیشنهاد داد داستان را قبل از تولدت بسازیم.« آرن ساکت شد.\n«ولی تو فقط یک چیز را اشتباه فهمیدی.«\n«چی؟« لیان گفت:\n«فکر کردی اگر مردم را از تو بترسانیم، جلوی آینده را گرفته‌ایم.« مکث کرد.\n«در حالی که فقط داشتیم آینده‌ای می‌ساختیم که از آن می‌ترسیدیم.«\nصدای زنگی از بیرون آمد. مردم در میدان جمع شده بودند. یک پیام تازه منتشر شده بود. آرن و لیان به میدان رفتند. روی سکوی مرکزی، مردی از شورای پیشگیری ایستاده بود و در دستش سندی بود.\n«به فرمان شورای عالی، از امروز آرن مسئول حفظ نظم در هفت شهر خواهد بود.« همهمه. آرن گفت:\n«من قبول نکردم.« مرد گفت:\n«مردم قبول کردند.« آرن رو به جمعیت کرد.\n«شما خواستید؟« صدها صدا با هم پاسخ دادند:\n«بله.«\n«چرا؟« مردی گفت:\n«چون تو تنها کسی هستی که می‌تونه جلوی آشوب رو بگیره.« زن دیگری گفت:\n«چون قاضی‌ها از تصمیم گرفتن می‌ترسن.« دیگری:\n«چون فرمانداران منتظر تو هستند.« و کودکی از میان جمعیت فریاد زد:\n«چون تو می‌دونی!«\nآرن چشم‌هایش را بست. این جمله را قبلاً شنیده بود. درست همان چیزی که نمی‌خواست. تو می‌دانی. آرن چشم باز کرد.\n«نه.« جمعیت ساکت شد.\n«من نمی‌دونم.« صدای اعتراض بلند شد.\n«اما...« آرن دستش را بالا آورد.\n«و اگر روزی فکر کردم می‌دونم، شما باید اولین کسانی باشید که جلوی من می‌ایستید.« مردم چیزی نگفتند. آرن ادامه داد:\n«من نمی‌خوام پادشاه شما باشم.« یکی از جمعیت گفت:\n«پس چرا این‌همه قدرت داری؟« آرن جواب داد:\n«قدرت داشتن، دلیل حق داشتن نیست.« این بار سکوت طولانی‌تر بود.\nآن شب، شورای پیشگیری جلسه گرفت. کالن گفت:\n«او قبول نکرد.« یکی از اعضا پرسید:\n«پس شکست خوردیم؟« کالن سرش را تکان داد.\n«نه.«\n«چرا؟« کالن سندی را بالا گرفت.\n«هفت شهر حالا منتظر تصمیم او هستند.«\n«اما او فرمان نداد.«\n«فرقی نمی‌کند.« کالن لبخند زد.\n«آنها منتظرند.«\nدر همان لحظه، در یکی ازهفت شهر، دو گروه بر سر آب درگیر شدند. قاضی از ترس تصمیم نگرفت. فرماندار منتظر شورا ماند. شورا گفت منتظر آرن باشید. مردم به میدان رفتند و کسی فریاد زد:\n«آرن باید تصمیم بگیره!« جمعیت تکرار کرد.\n«آرن باید تصمیم بگیره!«\nصدای آنها از دیوارها گذشت. از خیابان‌ها، خانه‌ها، اتاق‌های شورا و بالاخره به جایی رسید که آرن ایستاده بود. او صدا را شنید. سرش را پایین انداخت. یورن گفت:\n«می‌خوای کاری بکنی؟«\nآرن جواب نداد و چشم‌هایش را بست. هزاران امکان دوباره آشکار شدند. اگر دخالت کند، آرامش می‌آید. اگر دخالت نکند، احتمال خشونت بالا می‌رود. اگر یک نفر را مجبور کند، هزاران نفر آرام می‌شوند. اگر هیچ‌کس را مجبور نکند، ممکن است عده‌ای بمیرند و برای نخستین بار، یکی از مسیرها آن‌قدر سنگین شد که آرن نتوانست نادیده‌اش بگیرد. نه به خاطر خواست مردم. نه به خاطر شورا. نه به خاطر پیشگویی. به خاطر ترس خودش. آرن چشم باز کرد و گفت:\n«باشه.« یورن به او نگاه کرد.\n«چی؟« آرن آرام گفت:\n«این بار... فرمان می‌دم.«\nدر همان لحظه، چراغ‌های هفت شهر با هم روشن شدند و در دفتر شورای پیشگیری، کالن اولین صفحه‌ی کتابی را باز کرد که بعدها تاریخ آن را با یک نام خواهد شناخت: دوران آرن. اما هنوز کسی نمی‌دانست نخستین فرمان او چه خواهد بود.".split(/\n\n+/).filter(Boolean)
}
episodes[6] = {
  number:26,
  title:'تاج',
  paragraphs:"تاج را روی سرش گذاشتند. هیچ موسیقی‌ای نواخته نشد. هیچ آتشی در آسمان روشن نشد. هیچ نشانه‌ای از جانب آسمان نیامد. فقط مردی ایستاده بود با تاجی بر سر، و هزاران نفر که به او نگاه می‌کردند. اما آرن سنگینی آن را احساس کرد. نه روی سرش. درونش. انگار تمام نگاه‌هایی که طی هزار سال به نام او دوخته شده بودند، حالا یک‌جا روی شانه‌هایش نشسته بودند. کودکی در میان جمعیت گفت:\n«واقعاً پادشاه شد؟« مادرش آرام جواب داد:\n«نمی‌دانم.«\nآرن این را شنید و از میان هزاران صدا، همین دو کلمه به او آرامش داد. نمی‌دانم.\nکالن جلو آمد.\n«اکنون باید اولین فرمانت را صادر کنی.« آرن نگاهش کرد.\n«من قبلاً فرمان داده‌ام.«\n«این یکی فرق دارد.«\n«چطور؟« کالن به تاج اشاره کرد.\n«حالا همه می‌دانند که فرمان تو قانون است.« آرن به تاج دست زد.\n«پس اولین فرمانم اینه که هیچ فرمانی از من بدون دلیل اجرا نشه.«کالن اخم کرد.\n«این امکان‌پذیر نیست.« آرن گفت:\n«پس تاج چه فایده‌ای داره؟« کالن چیزی نگفت. آرن رو به مردم کرد.\n«هر فرمانی که می‌دم، باید دلیلش هم گفته بشه.« یکی از اعضای شورا اعتراض کرد:\n«مردم لازم نیست همه‌چیز رو بدونن.« آرن نگاهش کرد.\n«من میگم لازمه.«\nآن روز، مردم برای اولین بار متوجه شدند تاج آرن شبیه تاج پادشاهان پیشین نیست. او فرمان می‌داد. اما هر فرمان، همراه با دلیل بود. او مالیاتی را لغو کرد. چون می‌دانست ترس، مردم را فقیر کرده است. یک زندان را بست. چون زندانیان فقط به دلیل ارتباط با او در آنجا بودند. سه فرمانده را برکنار کرد. نه به خاطر مخالفتشان با او. به خاطر اینکه سربازان را برای ایجاد ترس میان مردم به کار برده بودند. هر تصمیم سریع بود. دقیق بود و مؤثر. شهرها آرام‌تر شدند. راه‌ها دوباره باز شدند. بازرگانان برگشتند. مردم دوباره به بازارها آمدند و برای نخستین بار، کسانی که سال‌ها از آرن ترسیده بودند، گفتند:\n«شاید اشتباه کرده بودیم.«\nاین جمله خطرناک بود. چون مردم به سرعت از یک قطعیت به قطعیت دیگر می‌رفتند. دیروز: «او هیولاست.« امروز: «او نجات‌دهنده است.« و آرن می‌دانست هر دو جمله می‌توانند یک خطر داشته باشند. یک روز به یورن گفت:\n«من از نفرت کمتر از این می‌ترسم.« یورن پرسید:\n«از چی؟«\n«از اینکه دوباره منو باور کنن.«\nدر پایتخت، لیان هنوز آزاد بود. او را زندانی نکرده بودند. اما دیگر اجازه‌ی حضور در شورا را نداشت. یک شب آرن به دیدنش رفت. لیان در اتاقی کوچک زندگی می‌کرد. کتاب‌ها همه‌جا بودند. آرن گفت:\n«تو چرا فرار نکردی؟« لیان گفت:\n«از چی؟«\n«از من.« لیان لبخند زد.\n«فکر می‌کنی اگر می‌خواستم، می‌توانستم؟« آرن جواب نداد. لیان به تاج نگاه کرد.\n«سنگینه؟«\n«خیلی.«\n«خوبه.« آرن اخم کرد.\n«چرا؟« لیان گفت:\n«قدرتی که سبک به نظر بیاد، معمولاً قدرت خطرناکیه.«\nآرن دفتر سِراخ را روی میز گذاشت.\n«یه سؤال دارم.«\n«بپرس.«\n«چرا تو هنوز به من می‌گی آزاد؟« لیان ساکت شد.\n«من الان پادشاه‌ام.«\n«بله.«\n«پس آزاد نیستم.« لیان گفت:\n«پادشاه بودن با آزاد بودن تناقض ندارد.«\n«اما همه انتخاب‌های من روی زندگی دیگران اثر می‌گذاره.«\n«انتخاب هر انسانی همین‌طور است.«\n«نه به این اندازه.« لیان گفت:\n«درسته.« مکث کرد.\n«برای همین مسئولیتت هم بیشتر است.« آرن گفت:\n«پس آزادی یعنی مسئولیت بیشتر؟« لیان جواب داد:\n«گاهی.« آرن به پنجره نگاه کرد. شهر آرام بود.\n«من می‌تونم قدرت رو کنار بذارم.« لیان گفت:\n«می‌دونم.«\n«پس چرا هنوز اینجام؟« لیان پاسخ داد:\n«چون هنوز فکر می‌کنی اگر کنار بکشی، کسانی آسیب می‌بینند.« آرن چیزی نگفت. لیان ادامه داد:\n«این همون جاییه که باید مراقب باشی.«\n«چرا؟«\n«چون ممکنه روزی به خودت بگی: فقط این یک بار.« آرن لبخند تلخی زد.\n«و بعد؟«\n«بعد فقط یک بار دیگه.«\nماه‌ها گذشت. آرن بهتر حکومت می‌کرد، اما هرچه بهتر حکومت می‌کرد، وابستگی مردم بیشتر می‌شد. اگر قاضی تصمیمی می‌گرفت، مردم می‌گفتند: «باید از آرن بپرسیم.« اگر فرماندار اشتباه می‌کرد: «آرن باید عوضش کنه.« اگر محصولی کم می‌شد: «آرن باید کاری کنه.« اگر کودکی بیمار می‌شد: «آرن باید نجاتش بده.« و آرن هر روز بیشتر در مرکز جهان قرار می‌گرفت. نه چون خودش خواسته بود. چون مردم، آرام‌آرام، مسئولیت‌های خودشان را به او می‌دادند.\nروزی زنی نزد او آمد.\n«پسرم رو نجات بده.« آرن گفت:\n«چه اتفاقی افتاده؟»\n«بیماره.«\n«پزشک؟«\n«پزشک گفت امیدی نیست.«\nآرن به کودک نگاه کرد. می‌توانست احتمال بهبود را تغییر دهد. می‌توانست اما اگر این کار را می‌کرد، چه؟ اگر برای یک نفر انجام می‌داد، چرا برای دیگری نه؟ و اگر برای همه؟ چه چیزی از انتخاب و مسئولیت باقی می‌ماند؟ زن گریه کرد.\n«تو می‌تونی.« آرن گفت:\n«می‌تونم تلاش کنم.«\n«نه.« زن سرش را تکان داد.\n«تو می‌تونی نجاتش بدی.« آرن گفت:\n«نمی‌دونم.« زن با ناامیدی گفت:\n«پس چرا تاج گذاشتی؟«\nکودک آن شب مرد. آرن هیچ کاری نکرده بود اما برای نخستین بار، مردم از او ناراحت شدند. نه چون کاری کرده بود. چون کاری نکرده بود. شایعه شروع شد: «آرن می‌توانست نجاتش دهد و نداد.« بعد: «آرن تصمیم می‌گیرد چه کسی زنده بماند.« بعد: «او برای مردم ارزش یکسانی قائل نیست.« آرن خبرها را خواند. کاغذ را کنار گذاشت. یورن گفت:\n«می‌دونستی این اتفاق می‌افته.«\n«بله.«\n«پس چرا ناراحتی؟« آرن جواب داد:\n«چون می‌تونستم.« این جمله در ذهنش ماند. چون می‌تونستم. نه «باید«. نه «حق داشتم« فقط: می‌توانستم.\nآن شب، آرن دوباره سراغ دفتر سِراخ رفت. صفحه‌های آخر را ورق زد. در یکی از صفحات، جمله‌ای بود که قبلاً ندیده بود: «خطرناک‌ترین لحظه برای یک موجود قدرتمند، زمانی نیست که قدرتش را کشف می‌کند.« صفحه‌ی بعد: «زمانی است که برای اولین بار می‌فهمد می‌تواند کاری را انجام دهد و انتخاب می‌کند که انجام ندهد.« صفحه‌ی بعد: «زیرا از آن لحظه به بعد هر نتیجه‌ای که رخ دهد، می‌تواند در ذهن او به شکل یک انتخاب باقی بماند.« آرن دفتر را بست.\nصبح روز بعد، فرمانی صادر کرد. «هیچ‌کس حق ندارد از آرن بخواهد درباره‌ی مرگ و زندگی انسان‌ها تصمیم بگیرد، مگر آنکه خودش شخصاً در خطر باشد.« مردم خشمگین شدند. کسی گفت: «پس پادشاه به چه درد می‌خوره؟« آرن جواب نداد. اما در میان مردم، گروه کوچکی از فیلسوفان و دانشمندان این فرمان را تحسین کردند. آنها گفتند: «او برای قدرت خودش حد تعیین کرده.« و گروه دیگری گفت: «او از مسئولیت فرار می‌کند.« هر دو گروه، بخشی از حقیقت را می‌گفتند.\nسه ماه بعد، اتفاقی افتاد که همه‌چیز را تغییر داد. در شمال، شورشی شکل گرفت. نه علیه آرن. به نام آرن. گروهی مسلح ادعا کردند که تنها آنها «اراده‌ی واقعی آرن« را می‌فهمند. آنها روستاها را گرفتند. مخالفان را کشتند. خانه‌ها را آتش زدند و روی دیوارها نوشتند: «به نام آرن.« خبر که رسید، آرن چیزی نگفت. یورن گفت:\n«باید جلوشون رو بگیری.« آرن گفت:\n«بله.«\n«پس چرا نمی‌ری؟« آرن به تاج نگاه کرد.\n«این بار فرق داره.«\n«چه فرقی؟« آرن گفت:\n«این بار دارن به اسم من می‌کشن.«\nاو ارتش را فراخواند و برای نخستین بار، خودش دستور جنگ داد. نه برای دفاع از خودش. نه برای گسترش قدرت. برای متوقف کردن کسانی که از نام او استفاده می‌کردند. پیش از حرکت، لیان به دیدنش آمد.\n«می‌دونی این شروع کجاست؟« آرن گفت:\n«می‌دونم.«\n«نه.« لیان سرش را تکان داد.\n«هنوز نمی‌دونی.« آرن نگاهش کرد. لیان گفت:\n«تو امروز برای اولین بار تصمیم گرفتی که چه کسی حق دارد به نام تو زندگی کند.« آرن پاسخ داد:\n«و چه کسی حق ندارد به نام من بکشد.« لیان گفت:\n«مرز باریکی است.« آرن گفت:\n«ولی باید باشد.«\nارتش به شمال رفت. شورش در سه روز شکست خورد. آرن دستور داد رهبران زنده بمانند و محاکمه شوند. مردم جشن گرفتند. پرچم‌ها بالا رفت. کودکان نامش را فریاد زدند. آرن اما شب، تنها کنار رودخانه ایستاد. آب آرام بود. او تاج را از سر برداشت. در آب نگاه کرد. چهره‌ی خودش را دید و برای لحظه‌ای، چهره‌ی دیگری روی آب ظاهر شد. مردی پیر، با تاجی سیاه و چشمانی خالی. آرن پلک زد. تصویر ناپدید شد. اما صدایی در ذهنش ماند:\n«این هنوز تو نیستی.« آرن گفت:\n«پس کیه؟« رودخانه پاسخ نداد.\nدر دوردست، هزاران چراغ روشن شد. نه به فرمان او. به فرمان کسانی که دیگر خودشان را پیرو نمی‌دانستند. خودشان را فرمان‌بردار می‌دانستند و آرن برای نخستین بار فهمید: تاج را می‌توان از سر برداشت، اما چیزی که مردم در ذهن خودشان می‌سازند، به این آسانی برداشته نمی‌شود. او هنوز پادشاه بود. هنوز عادل بود. هنوز نمی‌خواست کسی را به بردگی بگیرد. اما جهان، آرام‌آرام، داشت برایش دلیلی می‌ساخت که روزی چنین کاری را «ضروری« بداند.\nدورتر از همه‌ی اینها، در اتاقی تاریک، کالن آخرین صفحه‌ی گزارشی را امضا کرد: «مرحله‌ی اول موفق شد.« زیر آن، یک جمله‌ی کوتاه‌تر اضافه کرد: »حالا باید او را مجبور کنیم از مردم بترسد.«".split(/\n\n+/).filter(Boolean)
}
episodes[7] = {
  number:27,
  title:'مردم',
  paragraphs:"کالن دیگر به آرن حمله نمی‌کرد. او فهمیده بود حمله، آرن را قوی‌تر می‌کند. هر دشمنی که شمشیر می‌کشید، به آرن دلیلی برای دفاع می‌داد. هر توطئه‌ای که کشف می‌شد، اعتماد مردم به او را بیشتر می‌کرد. هر خیانتی، مرز میان «او« و «آنها« را ضخیم‌تر می‌کرد. پس کالن روش دیگری انتخاب کرد. او تصمیم گرفت بجای آنکه آرن را از مردم بترساند، مردم را طوری تغییر دهد که آرن حق داشته باشد از آنها بترسد.\nاولین خبر، از غرب آمد. یک فرماندار به قتل رسید. قاتل هنگام دستگیری فقط یک جمله گفت: «به نام آرن.« روز بعد، دو سرباز کشته شدند. باز هم: «به نام آرن.« سه روز بعد، انبار غله‌ای آتش گرفت. روی دیوار نوشته بودند: «برای آینده‌ای که آرن وعده داده.« آرن گزارش‌ها را خواند. یورن گفت:\n«این‌ها شورشی‌های قبلی نیستن.«\n«می‌دونم.«\n«پس کی‌ان؟« آرن گفت:\n«نمی‌دونم.« و این‌بار، «نمی‌دانم« آرامش نیاورد.\nگزارش چهارم رسید. یک مدرسه. بیست کودک. یک معلم. معلم از آنها خواسته بود تصویر آرن را از دیوار پایین بیاورند. کودکان مخالفت کرده بودند. یکی از آنها چاقویی آورده بود. معلم کشته شده بود. قاتل دوازده ساله بود. وقتی او را گرفتند، فقط گریه می‌کرد. آرن وقتی خبر را شنید، گفت:\n«بیاریدش اینجا.« یورن پرسید:\n«برای چی؟«\n«می‌خوام ببینمش.«\nکودک را آوردند. کوچک بود و لاغر. با صورتی که هنوز آثار کودکی در آن مانده بود. آرن مقابلش نشست.\n«چرا کشتیش؟« کودک گریه کرد.\n«گفت شما هیولا هستید.« آرن ساکت ماند.\n«گفت نباید بهتون اعتماد کنیم.« آرن پرسید:\n«چرا به من اعتماد کردی؟« کودک سرش را بلند کرد.\n«چون همه می‌گفتن شما ما رو نجات می‌دید.«\nآرن احساس کرد چیزی درونش فرو ریخت. نه از خشم. از خستگی. این کودک نه او را می‌شناخت. نه مقتول را. او فقط یکی از داستان‌ها را باور کرده بود. آرن گفت:\n«برو.« نگهبان تعجب کرد.\n«ولی...«\n«ببرینش پیش مادرش.« کودک بلند شد. قبل از خروج برگشت.\n«تو منو نمی‌کشی؟« آرن گفت:\n«نه.« کودک پرسید:\n«چرا؟« آرن جواب داد:\n«چون نمی‌خوام چیزی که درباره‌ی من گفتن، به حقیقت تبدیل بشه.« کودک رفت. یورن گفت:\n«این تصمیم درسته؟« آرن به در نگاه کرد.\n«نمی‌دونم.«\nهمان شب، نامه‌ای به دستش رسید. بدون نام. فقط یک جمله: «او را نکش. بگذار بزرگ شود و دیگران را بکشد.« آرن نامه را سوزاند. اما جمله در ذهنش ماند.\nهفته‌ی بعد، خشونت بیشتر شد. هرچه آرن بیشتر از کشتن خودداری می‌کرد، عده‌ای جسورتر می‌شدند. نه لزوماً چون او را ضعیف می‌دانستند. چون فهمیده بودند مرز او کجاست. آرن نمی‌کشت. پس می‌توانستند تا مرز مرگ نزدیک شوند. یک شب، گروهی مسلح وارد یکی از شهرها شدند. خانه‌ها را آتش زدند. مردم فرار کردند. ارتش رسید. اما مهاجمان میان مردم پنهان شدند. سربازان نمی‌دانستند چه کسی دشمن است. آرن وارد شهر شد. دود همه‌جا را پوشانده بود. زنی فریاد زد: «کمکمون کن!« کودکی گریه می‌کرد. مردی با لباس غیرنظامی پشت دیوار پنهان شده بود، اما چاقویی در دست داشت. آرن می‌توانست تشخیص دهد. امکان حمله را حس می‌کرد. دستش را بالا برد. چاقو افتاد و مرد فرار کرد. آرن دنبالش نرفت.\nصبح، همان مرد یکی از سربازان را کشت. این بار آرن او را پیدا کرد. مرد روی زمین افتاده بود. زخمی و بی‌سلاح. آرن بالای سرش ایستاد. مرد گفت:\n«می‌دونستم نمی‌کشیم.« آرن چیزی نگفت.\n«تو این کار رو نمی‌کنی.« آرن پرسید:\n«مطمئنی؟« مرد خندید.\n«همه می‌دونن.« آرن دستش را پایین آورد.\nبرای نخستین بار، قدرتش نه به عنوان امکان، بلکه به عنوان وسوسه‌ای نزدیک درونش حرکت کرد. می‌توانست. فقط یک لحظه. یک انتخاب. مرد را می‌کشت و شاید صد نفر دیگر زنده می‌ماندند. اما اگر امروز می‌کشت، فردا چه؟ آرن عقب رفت. «ببرینش.« سربازان او را بردند. اما در راه، مرد خندید. خنده‌اش تا مدت‌ها در ذهن آرن ماند.\nسه روز بعد، همان زندانی فرار کرد. دو نگهبان را کشت. چهار زندانی دیگر را آزاد کرد و به روستایی رفت. آنجا، یک خانواده را کشت. وقتی خبر رسید، آرن دیگر حرف نزد. یورن گفت:\n«این تقصیر تو نیست.« آرن گفت:\n«نه.« مکث.\n«ولی انتخاب من بود.« یورن گفت:\n«انتخابت این بود که نکشی.« آرن جواب داد:\n«بله.«\n«پس چرا خودتو سرزنش می‌کنی؟« آرن به او نگاه کرد.\n«چون قدرت من فقط برای من نیست.« یورن ساکت شد. آرن ادامه داد:\n«اگر من تصمیم نگیرم، دیگران تصمیم می‌گیرن.«\nآن شب، آرن وارد اتاق شورا شد. کالن منتظرش بود. آرن گفت:\n«تو این کار رو کردی.« کالن گفت:\n«چه کاری؟«\n«شورش‌ها.«\n«مدرکی داری؟« آرن چیزی نگفت. کالن نزدیک آمد.\n«نه، آرن. پس چرا این‌قدر مطمئنی؟ چون تو فکر می‌کنی من باید دشمن تو باشم؟« آرن گفت:\n«هستی.« کالن لبخند زد.\n«اما دشمنی که می‌توانی ببینی، خطرناک نیست.« آرن اخم کرد. کالن ادامه داد:\n«خطرناک آن چیزی است که مردم خودشان انجام می‌دهند.« آرن نزدیک او رفت.\n«اگر دستت رو پشت این کارها ببینم...« کالن گفت:\n«چه کار می‌کنی؟« سکوت.\n«منو می‌کشی؟« آرن نگاهش کرد. کالن آهسته گفت:\n«تو نمی‌کشی.« آرن گفت:\n«هنوز نه.« کالن برای لحظه‌ای ساکت شد و بعد لبخند زد.\n«همین کلمه را منتظر بودم.«\nآرن از اتاق بیرون آمد. در راهرو، لیان منتظرش بود.\n«شنیدم.« آرن گفت:\n«چی؟«\n«هنوز نه.« آرن ایستاد. لیان گفت:\n«تو برای اولین بار به کشتن فکر کردی.«\n«فکر کردن که جرم نیست.«\n«نه.« لیان نزدیک شد.\n«اما وقتی انسان به چیزی فکر می‌کند که قبلاً از آن متنفر بوده، باید بداند بخشی از جهان در حال تغییر است.« آرن گفت:\n«جهان تغییر نکرده.« لیان گفت:\n«تو کردی.« آرن به او خیره شد.\n«من هنوز همون آدمم.«\n«نه.« لیان آرام گفت:\n«تو هنوز همان آدمی، اما دیگر همان زندگی را نداری.« مکث.\n«این دو تا یکی نیستند.« آرن گفت:\n«پس چی باید بکنم؟« لیان جواب نداد. آرن دوباره پرسید:\n«چی باید بکنم؟« لیان گفت:\n«هیچ‌کس نمی‌دونه.« آرن لبخند بسیار کم‌رنگی زد.\n«بالاخره یک جواب درست.«\nچند روز بعد، اتفاقی افتاد که همه‌چیز را شکست. مارا ناپدید شد. نه نامه‌ای، نه اثری از درگیری و نه جسدی. فقط خانه‌ای خالی و پنجره‌ای باز و روی میز، همان شاخه‌ی خشک، اما این‌بار روی آن نوشته شده بود:\n«پرده را کنار بزن.« آرن وقتی خبر را شنید، هیچ حرفی نزد. یورن گفت:\n«می‌ریم پیداش می‌کنیم.« آرن گفت:\n«بله.«\n«هر جا باشه.«\n«بله.« یورن مکث کرد.\n«حتی اگر شورا باشه؟« آرن جواب نداد.\nآن شب، آرن تاج را از سر برداشت و روی میز گذاشت. به آن خیره شد. سپس گفت:\n«اگر کسی مادرم رو برده باشه...« یورن گفت:\n«می‌ریم پیداش می‌کنیم.« آرن ادامه داد:\n«اگر برای نجاتش مجبور بشم کاری کنم که قبلاً نمی‌کردم...« یورن ساکت شد. آرن به تاج نگاه کرد.\n«این بار نمی‌دونم می‌تونم متوقفش کنم یا نه.«\nدر پایتخت، کالن نامه‌ای دریافت کرد. فقط یک جمله: «طعمه آماده است.«او نامه را سوزاند، اما پیش از سوختن برای یک لحظه، کلمه‌ی آخر دیده شد: «مادر.« کالن به سمت پنجره رفت. در دوردست، چراغ‌های شهر یکی‌یکی خاموش می‌شدند. او زیر لب گفت: «حالا باید ببینیم یک پسر، برای مادرش تا کجا می‌رود.« و در همان لحظه، جایی بسیار دورتر، مارا چشم‌هایش را باز کرد. او در اتاقی تاریک بود. دست‌هایش بسته نبود. در باز بود اما بیرون، کسی نگهبانی نمی‌داد. مارا به آرامی از جا بلند شد. روی دیوار روبه‌رو، جمله‌ای نوشته شده بود: «اگر او برای نجات تو آمد، جهان را نجات نخواهد داد.« مارا مدتی به آن نگاه کرد. بعد لبخند بسیار کوچکی زد. و زیر آن، با تکه‌ای زغال، نوشت: «پس امیدوارم برای من نیاید.«".split(/\n\n+/).filter(Boolean)
}
episodes[8] = {
  number:28,
  title:'فریب',
  paragraphs:"مارا سه روز منتظر ماند. نه برای نجات. برای اینکه بفهمد چه کسی او را آورده است. در تمام این سه روز، هیچ‌کس وارد اتاق نشد. غذا می‌آمد. آب می‌آمد. اما هیچ چهره‌ای پشت در نبود. روز سوم، مارا متوجه چیزی شد. در اتاق قفل نبود. در تمام این مدت، در باز بود. او فقط تصور کرده بود که زندانی است. لبخند زد. «مثل پسرم.« و از اتاق بیرون رفت.\nراهرویی طولانی پیش رویش بود. روی دیوارها، صدها تصویر آویزان بود. تصویر آرن در سنین مختلف. شش ساله. ده ساله. چهارده ساله. بیست ساله. تصویری از روزی که نخستین بار شمشیر سرباز افتاد. تصویری از شهرهای خاموش. تصویری از تاج. مارا مقابل هر تصویر چند لحظه ایستاد. در آخرین تصویر، آرن با تاجی سیاه ایستاده بود. زیر آن نوشته بودند: «ظالم.« مارا دستش را روی تصویر کشید.\n»هنوز نه.«\nدر انتهای راهرو، دری سنگین قرار داشت. پشت آن اتاقی بزرگ بود. کالن آنجا نشسته بود. مارا وارد شد. کالن از جا بلند نشد.\n«خوش آمدید.« مارا گفت:\n«اگر می‌خواستی از من برای آوردن آرن استفاده کنی، لازم نبود این‌همه نمایش اجرا کنی.« کالن لبخند زد.\n«من نمی‌خوام آرن رو مجبور کنم که بیاد.«\n«پس چه می‌خواهی؟«\n«می‌خوام خودش تصمیم بگیره بیاد.« مارا چیزی نگفت. کالن ادامه داد:\n«هزار سال پیش، ما یک اشتباه کردیم.«\n«می‌دانم.«\n«نه. هنوز نمی‌دانی.« او پوشه‌ای روی میز گذاشت.\n«این، اولین نسخه است.« مارا به آن نگاه کرد. دستش کمی لرزید.\n«از کجا آوردی؟«\n«از جایی که هیچ‌کس فکر نمی‌کرد هنوز وجود داشته باشه.«\nکاغذها بسیار قدیمی بودند، اما نوشته‌ها واضح. مارا شروع به خواندن کرد. اولین جمله: «روزی خواهد آمد آن‌که پرده را کنار خواهد زد.« او ادامه داد. «پس از آمدنش، آنچه پنهان مانده، دیگر نمی‌تواند پنهان بماند.« صفحه بعد: «او چیزی را با خود خواهد آورد که پیش از او در این جهان نبوده.« مارا نفسش را حبس کرد. کالن گفت:\n«ادامه بده.« او خواند:\n«و جهان پس از او، دیگر جهان پیش از او نخواهد بود.« مارا صفحه را پایین گذاشت.\n«هیچ‌جا نگفته که او پادشاه می‌شه.«\n«نه.«\n«هیچ‌جا نگفته مردم رو می‌کشه.«\n«نه.«\n«هیچ‌جا نگفته هیولاست.«\n«نه.« مارا به کالن نگاه کرد.\n«پس این هزار سال چه بود؟« کالن گفت:\n«ترس.«\n»ترس یا طمع؟« کالن چیزی نگفت.\nدر همان لحظه، در شهری دور، آرن به سمت شمال حرکت می‌کرد. یورن کنار او بود. هیچ‌کدام حرف نمی‌زدند. تاج همراهشان نبود. آرن آن را در پایتخت گذاشته بود، اما هر دو می‌دانستند تاجی که از سر برداشته شود، الزاماً قدرتی که به آن متصل شده را از بین نمی‌برد. آرن ناگهان ایستاد.\n«یه چیزی اشتباهه.« یورن پرسید:\n«چی؟«\n«نمی‌دونم.«\nچند قدم جلوتر رفت. درختی خشک کنار جاده ایستاده بود. روی تنه‌اش نوشته شده بود: «اولین نسخه را بخوان.« آرن دستش را روی نوشته گذاشت. برای لحظه‌ای، جهان تغییر نکرد اما تعداد مسیرهای ممکن در ذهنش زیاد شد. او دید: کودکی که ممکن بود آن درخت را بشکند. مردی که ممکن بود آن را آتش بزند. پرنده‌ای که ممکن بود روی شاخه‌اش بنشیند. بارانی که ممکن بود هرگز نبارد و در میان همه‌ی آنها، یک امکان روشن‌تر بود. اتاقی با مادری که منتظر بود. آرن دستش را برداشت.\n«پیداش کردم.«\nدر پایتخت، مارا صفحه آخر را خواند. در پایین نسخه‌ی اصلی، جمله‌ای با خط دیگری نوشته شده بود: «این پیشگویی درباره‌ی آنچه او خواهد کرد نیست.« کالن آرام گفت:\n«بخوان.« مارا ادامه داد:\n«این پیشگویی درباره‌ی آن چیزی است که در حضور او دیگر نمی‌تواند پنهان بماند.« سکوت. کالن گفت:\n«می‌فهمی؟« مارا جواب داد:\n«بله.«\n«پس می‌فهمی چرا خطرناک بود.« مارا سرش را بلند کرد.\n«نه.« کالن اخم کرد.\n«چرا؟«\n«آشکار کردنش دلیل دروغ گفتن بیشتر نبود.« کالن از جا بلند شد.\n«تو نمی‌فهمی. اگر مردم می‌دانستند او چه قدرتی دارد، چه اتفاقی می‌افتاد؟« مارا گفت:\n«نمی‌دانم.«\n«دقیقاً.« کالن دستش را روی میز کوبید.\n«همین ندانستن، می‌توانست همه‌چیز را نابود کند.« مارا آرام گفت:\n«پس شما تصمیم گرفتید به جای ندانستن، دروغ بگویید.« کالن چیزی نگفت. مارا ادامه داد:\n«و طی هزار سال، هر نسل دروغ قبلی رو با ترس خودش تکمیل کرد.«\nآرن به شهر رسید. شهر ساکت بود. بیش از حد ساکت. روی دیوارها هیچ تصویر، هیچ شعار و هیچ پرچمی نبود. فقط یک جمله: «او خواهد آمد.« یورن گفت:\n«دامه.« آرن گفت:\n«می‌دونم.«\n«پس چرا می‌ری داخل؟« آرن به دروازه نگاه کرد.\n«چون مادرم اونجاست.«\nدروازه باز شد. هیچ سربازی حمله نکرد. هیچ‌کس جلو نیامد. مردم فقط از پنجره‌ها نگاه می‌کردند. آرن وارد خیابان اصلی شد. قدم‌هایش آهسته بود. هرچه جلوتر می‌رفت، حس می‌کرد تعداد انتخاب‌های ممکن اطرافش بیشتر می‌شود. کسی می‌توانست سنگی پرتاب کند. کسی می‌توانست در را ببندد. کسی می‌توانست به او کمک کند. کسی می‌توانست فرار کند. کسی می‌توانست بایستد. هیچ‌کدام قطعی نبود. اما یک مسیر، از همه سنگین‌تر شده بود. مسیر خشونت. آرن ایستاد. چشمانش را بست و عمداً تلاش کرد وزن آن مسیر را کم کند. نه با زور. با انتخاب خودش. چند سرباز اسلحه‌هایشان را پایین آوردند. یک مرد در را بست. زنی کودک خود را به داخل خانه کشید. یک پیرمرد از پنجره بیرون آمد و گفت:\n«آرن.« آرن نگاهش کرد. پیرمرد گفت:\n«ما نمی‌دونیم تو چی هستی.« آرن گفت:\n«منم نمی‌دونم.« پیرمرد آرام گفت:\n«پس شاید هنوز امیدی باشه.«\nآرن به ساختمان مرکزی رسید. در باز بود. داخل شد. کالن منتظرش بود اما مارا آنجا نبود. آرن گفت:\n«کجاست؟« کالن جواب نداد. آرن یک قدم جلو رفت.\n«کجاست؟« کالن گفت:\n«اول باید چیزی رو ببینی.«\nروی دیوار، صدها سند قرار داشت. نسخه‌های مختلف پیشگویی. نسخه‌ی نخست. نسخه‌ی دوم. نسخه‌ی سلطنتی. نسخه‌ی جنگی. نسخه‌ی مذهبی. نسخه‌ی کودکان. نسخه‌ی ارتش. نسخه‌ی علمی. نسخه‌ی هزارساله.\nآرن جلو رفت. یکی را برداشت. در نسخه‌ای نوشته شده بود: «او خواهد آمد و جهان را تغییر خواهد داد.« نسخه بعد: «او خواهد آمد و قدرت را خواهد گرفت.« نسخه بعد: «او خواهد آمد و مردم را مطیع خواهد کرد.« نسخه بعد: «او خواهد آمد و کسانی را که به او اعتماد کنند خواهد کشت.« آرن آخرین صفحه را برداشت. روی آن فقط یک جمله بود: «او خواهد آمد.« پرسید:\n«کدومش واقعی بود؟« کالن گفت:\n«اولی.«\n«و بقیه؟«\n«تفسیر.« آرن برگشت.\n«نه.« کالن نگاهش کرد.\n«چی؟« آرن گفت:\n«بقیه فقط تفسیر نبودن.« به اسناد اشاره کرد.\n«شما هر بار که چیزی بهش اضافه کردید، براش کاری هم کردید.« کالن ساکت ماند. آرن ادامه داد:\n«شما ارتش ساختید.«\n«بله.«\n«قانون نوشتید.«\n«بله.«\n«مردم رو ترسوندید.«\n«بله.«\n«منو تعقیب کردید.« کالن جواب نداد.\n«به مادرم رسیدید.« سکوت. آرن گفت:\n«شما فقط درباره‌ی من داستان ننوشتید.« نفسش سنگین شد.\n«شما جهانی ساختید که اون داستان توش منطقی به نظر برسه.«\nدر همان لحظه، دری در انتهای سالن باز شد. مارا بیرون آمد. آرن برای چند ثانیه هیچ کاری نکرد و فقط نگاهش کرد. بعد جلو رفت. مادر و پسر یکدیگر را در آغوش گرفتند. نه آسمان شکافت. نه زمین لرزید. نه هیچ نیرویی ظاهر شد. فقط دو انسان همدیگر را پیدا کردند. مارا در گوشش گفت:\n«اومدی.« آرن گفت:\n«آره.«\n«چرا؟« آرن مکث کرد.\n«چون فکر کردم باید نجاتت بدم.« مارا کمی عقب رفت. به چشمانش نگاه کرد.\n«و حالا؟« آرن گفت:\n«حالا فکر می‌کنم تو خودت می‌تونستی بیرون بیای.« مارا لبخند زد.\n«بالاخره فهمیدی.«\nکالن از دور به آنها نگاه می‌کرد. او انتظار داشت آرن خشمگین شود. انتظار داشت حمله کند. انتظار داشت تمام قدرتش را آزاد کند. اما آرن فقط مادرش را گرفت و از اتاق بیرون رفت. کالن فریاد زد:\n«فرار می‌کنی؟« آرن ایستاد. برنگشت.\n«نه.«\n«پس چرا منو نمی‌کشی؟« آرن چند لحظه ساکت ماند. بعد گفت:\n«چون اگر تو رو بکشم، ممکنه برای هزار سال بعد، دوباره یک داستان تازه شروع بشه.« و رفت.\nآن شب، در خانه‌ای دور از پایتخت، آرن و مارا کنار چراغ نشستند. مارا نسخه‌ی نخست را روی میز گذاشت. آرن آن را خواند. چندین بار. سپس پرسید:\n«مامان... این چیزی که من باید بیارم چیه؟« مارا جواب نداد.\n«تو می‌دونی؟«\n«نه.«\n«کسی می‌دونه؟« مارا به شعله‌ی چراغ نگاه کرد.\n«شاید.«\n«کی؟«\n«کسی که پیش از همه، این رو نوشته.« آرن گفت:\n«سِراخ؟« مارا سرش را تکان داد.\n«نه.«\n«پس کی؟« مارا صفحه را برگرداند.\nدر پشت نسخه‌ی نخست، نشانی بود که تا آن روز هیچ‌کس ندیده بود. نه نامی. نه جمله‌ای. فقط یک شکل، شبیه یک حلقه و با یک نقطه در مرکز. آرن دستش را روی آن گذاشت. چراغ خاموش شد و در تاریکی، صدایی شنیده شد. نه از بیرون. نه از درون. صدایی که انگار از فاصله‌ای بسیار دور، از میان هزار سال گذشته می‌آمد:\n«هدیه، چیزی نیست که من به تو داده‌ام.« آرن نفسش را حبس کرد. صدا ادامه داد:\n«هدیه، چیزی است که تو باید بتوانی انتخابش کنی.«\nچراغ دوباره روشن شد اما نسخه‌ی نخست دیگر روی میز نبود. جایش فقط یک جمله مانده بود: «آنها پیام‌آور تغییر را تغییر دادند.« آرن به جمله خیره ماند و برای نخستین بار فهمید: شاید پیشگویی هرگز درباره‌ی آمدن او نبود. شاید درباره‌ی چیزی بود که پس از انتخاب او ممکن می‌شد و آن انتخاب هنوز انجام نشده بود.".split(/\n\n+/).filter(Boolean)
}
episodes[9] = {
  number:29,
  title:'نجات',
  paragraphs:"صبح، آرن تاج را پس گرفت. نه برای حکومت. برای اینکه آن را جلوی خودش روی میز بگذارد. مارا روبه‌رویش نشسته بود. یورن کنار پنجره ایستاده بود. هیچ‌کدام درباره‌ی شب گذشته حرف نمی‌زدند. آرن به تاج نگاه کرد.\n«اگه هزار سال پیش، هیچ‌کس نمی‌ترسید...« مارا گفت:\n«باز هم ممکن بود اشتباه کنی.« آرن سر بلند کرد.\n«پس همه‌چیز تقصیر اون‌ها نیست.« مارا آرام گفت:\n«نه.« سکوتی طولانی افتاد.\nاین شاید سخت‌ترین حقیقتی بود که آرن در تمام عمرش شنیده بود. او دوست داشت همه‌چیز را گردن هزار سال ترس بیندازد. آسان‌تر بود. اگر آنها او را ساخته بودند، پس او فقط قربانی بود، اما اگر بخشی از آنچه شده بود، انتخاب خودش بود... آن‌وقت دیگر هیچ‌کس نمی‌توانست بار آن را از دوشش بردارد.\nظهر، خبر رسید که سه شهر شورش کرده‌اند. دو شهر خواستار بازگشت آرن بودند. شهر سوم خواستار مرگ او. یورن گفت:\n«باید ارتش رو بفرستیم.« آرن پرسید:\n«چرا؟«\n«چون اگر نفرستیم، جنگ می‌شه.«\n«و اگر بفرستیم؟« یورن چیزی نگفت. آرن ادامه داد:\n«ممکنه همون جنگی بشه که ازش می‌ترسیم.« یورن گفت:\n«پس چی کار کنیم؟« آرن به نقشه نگاه کرد.\nهفت شهر. سه رودخانه. چهار مسیر تجاری. صدها روستا. هزاران رابطه. تمام جهان برای او شبیه شبکه‌ای از شاخه‌ها شده بود. هر تصمیم، شاخه‌ای را سنگین می‌کرد. هر سکوت، شاخه‌ای دیگر را. او می‌توانست جنگ را کمتر محتمل کند. اما نمی‌توانست انتخاب مردم را از آنها بگیرد. آرن گفت:\n«هیچ ارتشی نمی‌فرستیم.« یورن با ناباوری نگاهش کرد.\n«اگه اشتباه کنی چی؟« آرن گفت:\n«ممکنه.«\n«پس؟«\n«اما این‌بار می‌خوام اشتباه من، انتخاب من باشه.«\nفرمان آرن همان روز منتشر شد: «هیچ سربازی برای سرکوب هیچ شهری اعزام نمی‌شود.«\nشهرها حیرت کردند. عده‌ای آن را ضعف نامیدند. عده‌ای آزادی. عده‌ای هم گفتند این آخرین مرحله‌ی نقشه‌ی اوست، اما چیزی تغییر کرد. شهرهایی که آماده‌ی جنگ بودند، مجبور شدند خودشان تصمیم بگیرند. بعضی‌ها مذاکره کردند. بعضی‌ها جدا شدند. بعضی‌ها جنگیدند. در یکی از شهرها، مردم برای نخستین بار فهمیدند که اگر آرن دستور ندهد، مسئولیت تصمیمشان دوباره به خودشان برمی‌گردد.\nجنگ کوتاه بود. اما بی‌هزینه نبود. هفتاد و سه نفر مردند. آرن وقتی عدد را شنید، مدت زیادی چیزی نگفت. بعد پرسید:\n«اگر ارتش می‌فرستادم؟« یورن گفت:\n«شاید بیشتر می‌مردند.« آرن گفت:\n«شاید کمتر.« یورن جواب نداشت. آرن به پنجره نگاه کرد.\n«قدرت داشتن یعنی همین.«\n«چی؟«\n«هیچ‌وقت نمی‌فهمی کدوم زندگی‌ها رو با انتخابت نجات دادی.«\nچند روز بعد، کالن را پیدا کردند. نه در قصر. نه در زندان. در همان آرشیوی که هزار سال دروغ در آن نگهداری شده بود. او کنار دیوار نشسته بود. تمام نسخه‌های پیشگویی اطرافش ریخته بودند. آرن وارد شد. کالن لبخند زد.\n«بالاخره اومدی.« آرن چیزی نگفت. کالن گفت:\n«می‌دونی چرا نتونستی منو بکشی؟« آرن جواب داد:\n«چون نمی‌خواستم.« کالن خندید.\n«نه.«\n«پس چرا؟«\n«چون هنوز فکر می‌کنی نجات ممکنه.« آرن به او نزدیک شد.\n«نجات تو؟«\n«نجات خودت.« سکوت. کالن یکی از نسخه‌ها را برداشت.\n«تو هنوز می‌خوای ثابت کنی هیولا نیستی.« آرن گفت:\n«نه.«\n«پس چی؟«\n«دیگه برام مهم نیست.« کالن برای نخستین بار جدی شد. آرن ادامه داد:\n«من هیولا نیستم نه چون تو گفتی هستم.« مکث کرد.\n«و هیولا هم نمی‌شم نه چون تو گفتی می‌شم.« کالن پرسید:\n«پس چی تعیینش می‌کنه؟« آرن به تاجی که همراهش آورده بود نگاه کرد.\n«انتخاب‌هام.« کالن آرام خندید.\n«پس انتخاب کن.« آرن نگاهش کرد.\n«چی؟«\n«منو بکش.« سکوت.\n«تمامش کن.« کالن جلو آمد.\n«هزار سال پیش، مردی ترسید. بعد یک دروغ گفت. بعد مردهای دیگری آن را کامل کردند. بعد شهرها، ارتش‌ها، دانشمندان و پادشاهان. همه منتظر بودند تو همان چیزی بشوی که نوشته بودند.« چشمانش برق زد.\n«حالا اگر منو بکشی، بالاخره حق با همه‌شون می‌شه.« آرن گفت:\n«و اگر نکشم؟« کالن لبخند زد.\n«آن‌وقت باید با این واقعیت زندگی کنی که هنوز نمی‌دانی چه کسی هستی.«\nآرن مدت زیادی به او نگاه کرد. بعد شمشیرش را بیرون آورد. یورن نفسش را حبس کرد. آرن شمشیر را روی زمین گذاشت.\n«حق با هیچ‌کدوم‌مون نیست.« کالن گفت:\n«پس چرا زنده‌ام می‌گذاری؟« آرن جواب داد:\n«چون نمی‌خوام انتخابم رو تو تعیین کنی.«\nکالن دستگیر شد. اما آرن دستور اعدام نداد. او را در همان زندانی گذاشتند که سال‌ها پیش مخالفان آرن در آن نگهداری می‌شدند. بی‌تاج، بی‌قدرت، بی‌نام و برای نخستین بار، کسی مجبور نبود درباره‌ی آینده‌ی او تصمیم بگیرد.\nماه‌ها گذشت. شهرها دوباره باز شدند. نه به فرمان آرن. به انتخاب خودشان. برخی هنوز از او متنفر بودند. برخی دوستش داشتند. برخی او را نجات‌دهنده می‌دانستند. برخی هیولا، اما چیزی عجیب رخ داده بود. کم‌کم مردم شروع کردند به گفتن جمله‌ای که هزار سال از آن می‌ترسیدند: «نمی‌دانیم.«\nدر مدرسه‌ها، دیگر کودکان فقط یک نسخه از پیشگویی را نمی‌خواندند. تمام نسخه‌ها را می‌دیدند. در کتابخانه‌ها، تاریخ رسمی کنار تاریخ حذف‌شده قرار گرفت. در تالارهای علمی، عبارت «ظهور تابع رابطه است« به عنوان یک نظریه پذیرفته شد؛ نه درباره‌ی آرن، بلکه درباره‌ی ساختار انتخاب و امکان و در میدان اصلی پایتخت، مجسمه‌ای که آرن را با تاج سیاه نشان می‌داد پایین آورده شد. جای آن هیچ مجسمه‌ای نگذاشتند. فقط سنگی ساده. روی آن نوشته بود: «ما نمی‌دانیم.«\nسال‌ها بعد، آرن دیگر پادشاه نبود. تاج را در روزی نامعلوم کنار گذاشته بود. نه استعفا کرده بود. نه کسی برکنارش کرده بود. فقط یک صبح از تالار سلطنتی بیرون آمده و دیگر برنگشته بود. مردم ابتدا دنبال او گشتند. بعد خسته شدند. بعد یاد گرفتند بدون او تصمیم بگیرند. آرن در خانه‌ای کوچک نزدیک رودخانه زندگی می‌کرد. موهایش سفید شده بود. گاهی کودکان روستا به دیدنش می‌آمدند. یک روز دختربچه‌ای پرسید:\n«واقعاً تو همونی هستی که توی کتاب‌ها نوشته؟« آرن خندید.\n«کدوم کتاب؟« دختر کتاب قطوری را بالا گرفت.\n«همه‌شون.« آرن گفت:\n«پس احتمالاً نه.« دختر خندید. بعد پرسید:\n«تو دنیا رو نجات دادی؟« آرن به رودخانه نگاه کرد. آب آرام می‌گذشت.\n«نه.«\n«پس کی نجاتش داد؟« آرن مدتی فکر کرد.\n«نمی‌دونم.« دختر ناراحت شد.\n«تو که همه‌چیز رو می‌دونی.« آرن سرش را تکان داد.\n«نه.« و برای نخستین بار، ندانستن برایش شبیه شکست نبود. شبیه آزادی بود.\nآن شب، مارا نامه‌ای را که سال‌ها نگه داشته بود، سوزاند. یورن پرسید:\n«چرا حالا؟« مارا گفت:\n«چون دیگه لازم نیست کسی این رو بخونه.«\n«چی توش بود؟« مارا به خاکستر نگاه کرد.\n«آخرین دستور.« یورن پرسید:\n«از طرف چه کسی؟« مارا لبخند زد.\n«از طرف هیچ‌کس.«\nآن سوی شهر، پیرمردی برای نوه‌اش داستان آرن را تعریف می‌کرد. از هزار سال ترس گفت. از پیشگویی. از جنگ‌ها. از تاج. از شهرهای خاموش. از مردی که قدرت داشت و گاهی از آن استفاده کرد. از مردی که اشتباه کرد. از مردی که بعضی‌ها را نجات داد و بعضی‌ها را نتوانست. کودک پرسید:\n«پس آرن خوب بود یا بد؟« پیرمرد مکث کرد.\nسال‌ها پیش، چنین سؤالی پاسخ ساده‌ای داشت. قهرمان یا هیولا، اما پیرمرد به شعله‌ی چراغ نگاه کرد. به هزار سالی که مردم برای فرار از ندانستن، پاسخ ساخته بودند و گفت:\n«نمی‌دانم.« کودک گفت:\n«ولی تو داستانش رو می‌دونی.« پیرمرد لبخند زد.\n«داستان رو می‌دونم.«\n«پس چرا نمی‌دونی؟« پیرمرد چراغ را پایین کشید.\n«چون بالاخره یاد گرفتیم بین داستان و حقیقت فرق بگذاریم.«\nبیرون، باران شروع شد. قطره‌ها روی رودخانه افتادند و در جایی دور، شاخه‌ای خشک دوباره جوانه زد. این بار هیچ‌کس آن را نشانه ندانست. هیچ‌کس برایش پیشگویی ننوشت. هیچ‌کس از آن نترسید و جهان، برای نخستین بار پس از هزار سال، اجازه داد چیزی فقط اتفاق بیفتد. بدون اینکه بداند چرا.".split(/\n\n+/).filter(Boolean)
}
episodes[10] = {
  number:30,
  title:'ندانستن',
  paragraphs:"باران تا صبح ادامه داشت. رودخانه بالا آمده بود، اما خانه‌ی آرن هنوز برپا بود. او صبح زود بیدار شد. سال‌ها بود که خواب‌هایش دیگر درخت نداشتند. دیگر هزاران شاخه و هزاران امکان را نمی‌دید. قدرتش هنوز وجود داشت، اما کمتر به آن دست می‌زد. نه از ترس. از احترام. او فهمیده بود بعضی چیزها وقتی فقط می‌توانند اتفاق بیفتند، باید فرصت اتفاق افتادن داشته باشند، حتی اگر نتیجه‌شان دردناک باشد.\nروی میز، یک جعبه‌ی چوبی قرار داشت. جعبه‌ای که مارا پیش از مرگش به او داده بود. آرن سال‌ها آن را باز نکرده بود. روی درِ جعبه فقط یک کلمه نوشته شده بود: «آخر.« آن را باز کرد. داخلش یک برگ کاغذ بود. دست‌خط مارا. آرن شروع به خواندن کرد.\n«پسرم، اگر این نامه را می‌خوانی، یعنی دیگر لازم نیست کسی تو را نجات بدهد. نه من. نه مردم. نه حتی خودت.« آرن مکث کرد. ادامه داد.\n«تمام عمرت دنبال این بودی که بفهمی چه کسی تو را ساخته. آنها؟ ترس؟پیشگویی؟ انتخاب‌های خودت؟ شاید همه. شاید هیچ‌کدام.« در پایین صفحه نوشته بود:\n«اما یک چیز را فراموش نکن: اینکه دیگران در ساختن شرایط زندگی تو نقش داشته‌اند، به این معنا نیست که انتخاب‌های تو دیگر انتخاب تو نیستند.«\nآرن چشم‌هایش را بست. این همان چیزی بود که تمام این سال‌ها از آن فرار کرده بود. نه هیولا بودن. نه قهرمان بودن. بلکه مسئول بودن.\nدر جعبه، صفحه‌ی دیگری بود. این یکی متعلق به سِراخ بود. خطش لرزان بود. احتمالاً در آخرین روزهای زندگی‌اش نوشته شده بود:\n«اگر او روزی تاج را کنار بگذارد، پیشگویی محقق نشده است. اگر تاج را نگه دارد نیز هنوز محقق نشده است. پیشگویی نه در تاج است، نه در سقوط. چیزی که قرار بود با او بیاید، یک شیء نیست. یک فرمان هم نیست. یک قدرت هم نیست.« آرن ادامه را خواند.\n«او باید چیزی را به جهان نشان دهد که پیش از او نتوانسته بود وجود داشته باشد: انتخابی که از یقین فرار نمی‌کند، اما به آن هم تسلیم نمی‌شود.« آرن آرام گفت:\n«ندانستن.« صدایی پشت سرش آمد.\n«نه.« آرن برگشت.\nمارا نبود. یورن هم نبود. پیرمردی کنار در ایستاده بود. سِوِن اما پیرتر از همیشه. تقریباً شبیه سایه‌ای از یک انسان. آرن گفت:\n«فکر کردم مردی.« سِوِن لبخند زد.\n«خیلی‌ها همین فکر رو کردند.« سِوِن وارد اتاق شد. به رودخانه نگاه کرد.\n«پس بالاخره پیداش کردی.« آرن کاغذ را بالا گرفت.\n«این؟«\n«نه.«\n«پس چی؟« سِوِن گفت:\n«آنچه پیش از تو در جهان نبود.« آرن مدتی ساکت ماند.\n«تو می‌دونی چیه؟«\n«می‌دانستم.«\n«و حالا؟« سِوِن لبخند زد.\n«حالا نمی‌دانم.« آرن خندید. برای اولین بار، هر دو خندیدند. سِوِن کنار پنجره نشست.\n«می‌خوای حقیقت رو بشنوی؟« آرن گفت:\n«بعد از هزار سال دروغ؟ آره.«\n«حقیقت اینه که پیشگویی هیچ‌وقت نمی‌گفت تو چه کسی خواهی شد.«\n«می‌دونم.«\n«نه. این بخش رو هنوز نمی‌دونی.« سِوِن به او نگاه کرد.\n«پیشگویی حتی نمی‌گفت جهان بعد از تو بهتر خواهد شد.« آرن ساکت شد.\n«نمی‌گفت انسان‌ها نجات پیدا می‌کنند.« سکوت.\n«نمی‌گفت جنگ‌ها تمام می‌شوند.« سِوِن آرام گفت:\n«فقط می‌گفت جهان دیگر نمی‌تواند مثل قبل وانمود کند که می‌داند.« آرن به رودخانه نگاه کرد.\n«پس من نجات‌دهنده نبودم.«\n«نه.«\n«هیولا هم نبودم.«\n«نه.«\n«پس چی بودم؟« سِوِن گفت:\n«آزمایش.« آرن از جا بلند شد.\n«آزمایشِ چه کسی؟« سِوِن جواب نداد. آرن اصرار کرد:\n«خدا؟« سِوِن لبخند زد.\n«اگر وجود داشته باشد، شاید.«\n«پس جهان؟«\n«شاید.«\n«پس چه کسی؟« سِوِن به پنجره اشاره کرد.\nبیرون، کودکی در باران می‌دوید. زمین خیس بود. کودک لغزید و افتاد. بلند شد و دوباره دوید. سِوِن گفت:\n«شاید هیچ‌کس.« آرن به او نگاه کرد.\n«پس چرا پیشگویی؟«\n«چون انسان همیشه دوست دارد فکر کند پشت هر چیز، کسی ایستاده.«\nآن روز، آرن به شهر رفت. مردم او را شناختند، اما دیگر تعظیم نکردند. دیگر فرار هم نکردند. یک نانوا نان تازه‌ای به او داد. آرن پولش را پرداخت. نانوا گفت:\n«لازم نیست.« آرن گفت:\n«چرا؟« مرد خندید.\n«چون تو آرنی.« آرن پول را روی میز گذاشت.\n«دقیقاً به همین دلیل باید پولش رو بدم.«\nآرن برای لحظه‌ای به او نگاه کرد. بعد خندید و نان را گرفت. همین. نه معجزه‌ای رخ داد. نه چراغی روشن شد، اما شاید همین، چیزی بود که هزار سال پیش کسی نمی‌توانست تصور کند: آدمی می‌توانست آرن را دوست داشته باشد، بدون اینکه او را نجات‌دهنده بداند.\nسال‌ها بعد، کتاب‌های جدیدی درباره‌ی آرن نوشته شد. یکی او را قهرمان نامید. یکی مستبد. یکی قربانی. یکی بنیان‌گذار عصر جدید. یکی جنایتکاری که در پایان پشیمان شد. هیچ‌کدام کاملاً درست نبودند.\nدر جنگ شمال، آرن فرمانی داده بود که صدها نفر را نجات داد. همان فرمان، روستایی را بدون آب گذاشته بود.\nدر شورش جنوبی، او می‌توانست با قدرتش جنگ را متوقف کند. اما نکرد. هفتاد و سه نفر مردند.\nدر پایتخت، او کالن را نکشت اما سال‌ها پیش، فرمانی داده بود که باعث شد گروهی از سربازان وارد شهری شوند. بیست‌وهفت نفر کشته شدند.\nآرن بعدها فهمید می‌توانست راه دیگری را سنگین‌تر کند. نکرده بود. چون خسته بود. چون عصبانی بود. چون می‌ترسید. چون آن لحظه فکر کرده بود حق با اوست و هیچ پیشگویی نمی‌توانست این حقیقت را از او بگیرد.\nآخرین سال زندگی‌اش، آرن کنار رودخانه نشست. تاج دیگر وجود نداشت. کالن مرده بود. سِوِن ناپدید شده بود. یورن سال‌ها پیش در آرامش مرده بود. مارا هم. جهان ادامه داشت. همیشه همین کار را می‌کرد. ادامه می‌داد.\nآرن دستش را در آب فرو برد. برای لحظه‌ای، ظهور را احساس کرد. هزاران امکان. هزاران مسیر. هزاران «اگر«. می‌توانست یکی را انتخاب کند. می‌توانست آب را آرام کند. می‌توانست باران را متوقف کند. می‌توانست شاخه‌ای را به مسیر دیگری ببرد. اما دستش را بیرون آورد. آب همچنان جاری ماند. او دیگر نمی‌خواست جهان همیشه به حضور او پاسخ بدهد. شاید بزرگ‌ترین شکل آزادی همین بود: اینکه بتوانی تغییر بدهی، اما انتخاب کنی که تغییر ندهی.\nغروب، کودکی کنار رودخانه آمد. همان کودک نبود. نسل دیگری بود. پرسید:\n«تو آرنی؟« آرن گفت:\n«بودم.« کودک نشست.\n«می‌گن تو دنیا رو تغییر دادی.« آرن به افق نگاه کرد.\n«همه دنیا رو تغییر می‌دهند.«\n«چطوری؟«\n«با انتخاب کردن.« کودک فکر کرد.\n«پس منم دنیا رو تغییر می‌دم؟« آرن گفت:\n«حتی وقتی انتخاب نمی‌کنی.« کودک خندید.\n«این که خیلی سخت شد.« آرن هم خندید.\n«آره.«\nشب که شد، آرن به خانه برگشت. چراغ را روشن کرد. روی دیوار، جایی که سال‌ها پیش نوشته بودند «او خواهد آمد.« حالا جمله‌ی دیگری نوشته شده بود. نه از طرف پیشگو. نه از طرف پادشاه. نه از طرف دانشمند. با دست کودکی نوشته شده بود: «ما نمی‌دانیم چه خواهد شد.« آرن مدت زیادی به آن نگاه کرد. بعد زیرش نوشت:\n«اما انتخاب می‌کنیم.«\nچراغ را خاموش کرد. بیرون، باران شروع شد. رودخانه بالا آمد. درختان تکان خوردند و در دوردست، هزاران امکان همچنان وجود داشتند. هیچ‌کدام هنوز واقعیت نبودند. هیچ‌کدام هنوز دروغ نبودند. هیچ‌کدام وعده‌ی نجات نبودند. جهان فقط ایستاده بود، در آستانه‌ی رخ دادن و این‌بار، هیچ‌کس نمی‌دانست چه خواهد شد و برای نخستین بار، هیچ‌کس از این ندانستن نمی‌ترسید".split(/\n\n+/).filter(Boolean)
}

